28	
29	/*************************** Function Prototypes ************************/
30	
31	u8 KYPD_lookupShiftPattern(u16 shift);
32	
33	/************************** Function Definitions ************************/
34	
35	/* -------------------------------------------------------------------- */
36	/*** void KYPD_begin(PmodKYPD *InstancePtr, u32 GPIO_Address)
37	**
38	**   Parameters:
39	**      InstancePtr: A PmodKYPD device to start
40	**      GPIO_Address: The Base address of the PmodKYPD GPIO
41	**
42	**   Return Value:
43	**      none
44	**
45	**   Description:
46	**      Initialize the PmodKYPD driver device
47	*/
48	void KYPD_begin(PmodKYPD *InstancePtr, u32 GPIO_Address) {
49	   InstancePtr->GPIO_addr = GPIO_Address;
50	   // Set tri-state register, lower 4 pins are column outputs, upper 4 pins are
51	   // row inputs
52	   Xil_Out32(InstancePtr->GPIO_addr + 4, 0xF0);
53	   InstancePtr->keytable_loaded = FALSE;
54	}
55	
56	/* -------------------------------------------------------------------- */
57	/*** void KYPD_setCols(PmodKYPD *InstancePtr, u32 cols)
58	**
59	**   Parameters:
60	**      InstancePtr: A PmodKYPD device to use
61	**      cols: column bits to set the output pins to
62	**
63	**   Return Value:
64	**      none
65	**
66	**   Description:
67	**      Set the column output pins
68	*/
69	void KYPD_setCols(PmodKYPD *InstancePtr, u32 cols) {
70	   Xil_Out32(InstancePtr->GPIO_addr, cols & 0xF);
71	}
72	
73	/* -------------------------------------------------------------------- */
74	/*** u32 KYPD_getRows(PmodKYPD *InstancePtr)
75	**
76	**   Parameters:
77	**      InstancePtr: A PmodKYPD device to use
78	**
79	**   Return Value:
80	**      rows: row bits read from the input pins
81	**
82	**   Description:
83	**      Read the row input pins
84	*/
85	u32 KYPD_getRows(PmodKYPD *InstancePtr) {
86	   return (Xil_In32(InstancePtr->GPIO_addr) >> 4) & 0xF;
87	}
88	
89	/* -------------------------------------------------------------------- */
90	/*** u16 KYPD_getKeyStates(PmodKYPD *InstancePtr)
91	**
92	**   Parameters:
93	**      InstancePtr: A PmodKYPD device to use
94	**
95	**   Return Value:
96	**      keystate: 16 bits, each represents the status of one key (active high).
97	**                Each set of four keys on a single row are grouped together.
98	**
99	**   Description:
100	**      Capture the state of each key on the keypad
101	**
102	**   Errors:
103	**      Multiple key presses may not be detected properly - it can be detected
104	**      that multiple keys are pressed, but not which.
105	*/
106	u16 KYPD_getKeyStates(PmodKYPD *InstancePtr) {
107	   u32 rows, cols;
108	   u16 keystate;
109	   u16 shift[4] = {0, 0, 0, 0};
110	
111	   // Test each column combination, this will help to detect when multiple keys
112	   // in the same row are pressed.
113	   for (cols = 0; cols < 16; cols++) {
114	      KYPD_setCols(InstancePtr, cols);
115	      rows = KYPD_getRows(InstancePtr);
116	      // Group bits from each individual row
117	      shift[0] = (shift[0] << 1) | (rows & 0x1);
118	      shift[1] = (shift[1] << 1) | (rows & 0x2) >> 1;
119	      shift[2] = (shift[2] << 1) | (rows & 0x4) >> 2;
120	      shift[3] = (shift[3] << 1) | (rows & 0x8) >> 3;
121	   }
122	
123	   // Translate shift patterns for each row into button presses.
124	   keystate = 0;
125	   keystate |= KYPD_lookupShiftPattern(shift[0]);
126	   keystate |= KYPD_lookupShiftPattern(shift[1]) << 4;
127	   keystate |= KYPD_lookupShiftPattern(shift[2]) << 8;
128	   keystate |= KYPD_lookupShiftPattern(shift[3]) << 12;
129	   return keystate;
130	}
131	
132	/* -------------------------------------------------------------------- */
133	/*** void KYPD_loadKeyTable(PmodKYPD *InstancePtr, char keytable[16])
134	**
135	**   Parameters:
136	**      InstancePtr: A PmodKYPD device to use
137	**      keytable:    A 16-character array containing the characters that
138	**                   represent each key.
139	**
140	**   Return Value:
141	**      None
142	**
143	**   Description:
144	**      Set the keytable array so that KYPD_getKeyPressed will return will
145	**      return the human-readable character that the pressed key represents
146	*/
147	void KYPD_loadKeyTable(PmodKYPD *InstancePtr, u8 keytable[16]) {
148	   int i;
149	
150	   for (i = 0; i < 16; i++) {
151	      // Hard copy string into device struct
152	      InstancePtr->keytable[i] = keytable[i];
153	   }
154	
155	   InstancePtr->keytable_loaded = TRUE;
156	}
157	
158	/* -------------------------------------------------------------------- */
159	/*** XStatus KYPD_getKeyPressed(PmodKYPD *InstancePtr, u16 keystate, char *cptr)
160	**
161	**   Parameters:
162	**      InstancePtr: A PmodKYPD device to use
163	**      keystate:    Status of each key, pressed indicated by a '1' in that
164	**                      key's bit position.
165	**                   Bit positions correspond with character positions in
166	**                      InstancePtr->keytable.
167	**      cptr:        Address to return additional information when a single key
168	**                      is pressed.
169	**
170	**   Return Value:
171	**      status:
172	**         XST_SUCCESS when only one key is pressed.
173	**           cptr is loaded with a human-readable character when keytable is
174	**              loaded.
175	**           cptr is loaded with the key index when keytable is not loaded.
176	**       KYPD_MULTI_KEY when multiple keys are pressed.
177	**       KYPD_NO_KEY when no keys are pressed.
178	**
179	**  Errors:
180	**    KYPD_MULTI_KEY - cannot differentiate which keys are pressed in some
181	**                     multi-key cases.
182	**
183	**  Description:
184	**    Set the keytable array so that KYPD_getKeyPressed will return will
185	**    return the human-readable character that the pressed key represents
186	*/
187	u32 KYPD_getKeyPressed(PmodKYPD *InstancePtr, u16 keystate, u8 *cptr) {
188	   u8 i = 0;
189	   u8 ci = 0;
190	   u32 count = 0;
191	
192	   for (i = 0; i < 16; i++) {
193	      // If key reading is 0 (pressed)
194	      if (0x1 == (keystate & 0x1)) {
195	         count++; // Count the number of pressed keys
196	         ci = i;
197	      }
198	      // Increment through keystate bits
199	      keystate >>= 1;
200	   }
201	
202	   if (count > 1) {
203	      // Multiple keys pressed, cannot differentiate which
204	      return KYPD_MULTI_KEY;
205	   } else if (count == 0) {
206	      // No key pressed
207	      return KYPD_NO_KEY;
208	   } else {
209	      // One key pressed
210	      if (InstancePtr->keytable_loaded == TRUE)
211	         *cptr = InstancePtr->keytable[ci]; // Return human-readable key label
212	      else
213	         *cptr = ci; // Return index of pressed key
214	      return KYPD_SINGLE_KEY;
215	   }
216	}
217	
218	/* -------------------------------------------------------------------- */
219	/*** u8 KYPD_lookupShiftPattern(u16 shift)
220	**
221	**   Parameters:
222	**      InstancePtr: A PmodKYPD device to use
223	**      shift:       A 16-bit array containing the read bits of a single row
224	**                   received for each column pattern.
225	**
226	**   Return Value:
227	**      buttons: The button presses detected on this row.
228	**
229	**   Description:
230	**      Translates reading-pattern detected on a single row into the buttons
231	**      pressed on that row.
232	*/
233	u8 KYPD_lookupShiftPattern(u16 shift) {
234	   // Attempt to determine which keys are pressed in this row
235	   // These patterns were determined experimentally
236	   switch(shift) {
237	   case 0xFFFF: return 0x0;
238	   case 0x00FF: return 0x1;
239	   case 0x0F0F: return 0x2;
240	   case 0x0FFF: return 0x3;
241	   case 0x3333: return 0x4;
242	   case 0x33FF: return 0x5;
243	   case 0x3F3F: return 0x6;
244	   case 0x033F: return 0x7;
245	   case 0x5555: return 0x8;
246	   case 0x55FF: return 0x9;
247	   case 0x5F5F: return 0xA;
248	   case 0x055F: return 0xB;
249	   case 0x7777: return 0xC;
250	   case 0x1177: return 0xD;
251	   case 0x1717: return 0xE;
252	   case 0x177F: return 0xF;
253	   default:     return 0x0;
254	   }
255	}
